insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-30','verbeterd','Servicedesk','Gebruikt materiaal en opmerking voor kantoor in de app',
   'Op een servicedeskbon in de app kun je nu ook typen welk materiaal je hebt gebruikt, naast een foto van de pakbon; dit staat nu bovenaan, vóór Bon gereed melden. Met "Opmerking voor kantoor" stuur je tekst en foto''s naar kantoor: ze komen bij de notities van de bon en de projectleider krijgt een melding. De knop Projectbezoek is bij servicedeskbonnen verdwenen.'),
  ('2026-09-30','verbeterd','Dossiers','Bellen in de app belt het werkadres',
   'In de app zie je bij het werkadres nu ook de naam en het telefoonnummer van wie er ter plaatse is, en de knop Bellen belt dat nummer. De opdrachtgever en de contactpersoon staan samen in een eigen blok, met het nummer van de contactpersoon aan te tikken.'),
  ('2026-09-30','nieuw','Inkoop','Inkooporders en opdrachten openen en intrekken',
   'Op het tabblad Inkoop klik je op een leverancier of onderaannemer om te zien wat er precies besteld of opgedragen is. Vanuit dat venster kun je de order of opdracht ook intrekken, ook als hij al verstuurd is. EVA stuurt de partij daarover geen bericht, dus laat het ze zelf weten.');
